WITH with_windows AS (SELECT *, FIRST_VALUE(country, TRUE) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_country, ROW_NUMBER() OVER (PARTITION BY device, browser ORDER BY started_at DESC, id) event_seq, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_browser FROM sessions) SELECT id, customer_id, device, country, first_known_country FROM with_windows ORDER BY device DESC NULLS FIRST
